def public_video_edit_status_copy(locale: str = "vi") -> dict[str, str]:
    keys = ("receive","check","prepare","edit","validate","deliver","completed","delivery_unknown","failed","waiting","no_resend")
    key = str(locale or "vi").lower().replace("-", "_")
    if key not in _PUBLIC_VIDEO_EDIT_STATUS_COPY:
        key = "en"
    return {
        **dict(zip(keys, _PUBLIC_VIDEO_EDIT_STATUS_COPY[key], strict=True)),
        **dict(
            zip(
                _PUBLIC_VIDEO_EDIT_REPORT_KEYS,
                _PUBLIC_VIDEO_EDIT_REPORT_VALUES[key],
                strict=True,
            )
        ),
    }

