def public_video_finalization_shared_copy(locale: str = "vi") -> dict[str, str]:
    key = str(locale or "vi").lower().replace("-", "_")
    if key not in _PUBLIC_VIDEO_FINALIZATION_SHARED_COPY:
        key = "en"
    return {
        **dict(
        zip(
            ("source", "aspect_ratio", "logo_watermark", "source_aspect"),
            _PUBLIC_VIDEO_FINALIZATION_SHARED_COPY[key],
            strict=True,
        )),
        **dict(zip(_PUBLIC_VIDEO_FINALIZATION_DETAIL_KEYS, _PUBLIC_VIDEO_FINALIZATION_DETAIL_VALUES[key], strict=True)),
    }

