_PUBLIC_SUBDUB_DEEP_COPY = {
    locale: dict(zip(_PUBLIC_SUBDUB_DEEP_KEYS, values, strict=True))
    for locale, values in _PUBLIC_SUBDUB_DEEP_VALUES.items()
}

def public_subdub_deep_copy(locale: str = "vi") -> dict[str, str]:
    key = str(locale or "vi").lower().replace("-", "_")
    if key not in _PUBLIC_SUBDUB_DEEP_COPY:
        key = "en"
    return dict(_PUBLIC_SUBDUB_DEEP_COPY[key])


def public_subdub_auto_pricing_line(locale: str = "vi") -> str:
    copy = public_subdub_deep_copy(locale)
    return f"• {copy['voice_auto_speaker']}: {copy['voice_auto_price_rule']}"

