_PUBLIC_UI_TEXT_SECONDARY_LOCALES = (
    "ja", "ko", "th", "ar", "es", "pt", "fr", "de", "hi", "ru", "tr",
    "fil", "it", "id",
)


def public_ui_text_table() -> dict[str, dict[str, str]]:
    """Return complete native UI_TEXT overlays for supported secondary locales."""

    table = {
        locale: dict(zip(_PUBLIC_UI_TEXT_KEYS, _PUBLIC_UI_TEXT_VALUES[locale], strict=True))
        for locale in _PUBLIC_UI_TEXT_SECONDARY_LOCALES
    }
    # Repair the handful of labels that were corrupted by a legacy export.
    # These are display-only values; no callback or runtime behavior changes.
    table["ja"].update({
        "pricing.member_conditions": "🪪 会員条件",
        "media.job_lock": "⏳ 処理中のタスクがあります。結果が届くまでお待ちください。コマンドを再送する必要はありません。",
        "account.ref_link_title": "🎁 <b>あなたの TOAN AAS 紹介リンク：</b>",
        "media.creator_title": "🎨 TOAN AAS メディア作成\n\n何を作成しますか？",
    })
    table["es"]["motion.style.tutorial"] = "🧑‍🏫 Tutorial guiado"
    table["fil"]["motion.style.tutorial"] = "🧑‍🏫 Gabay na hakbang-hakbang"
    table["it"]["motion.style.tutorial"] = "🧑‍🏫 Guida passo passo"
    table["id"]["motion.style.tutorial"] = "🧑‍🏫 Panduan langkah demi langkah"
    # Keep stable product tokens readable when adjacent to translated prose.
    # An earlier generated export collapsed surrounding whitespace in several
    # locales (for example ``TOAN AASno`` and ``cobróXu``).
    tokens = ("TOAN AAS", "Xu", "AI", "Bot", "Scene", "prompt", "provider", "Admin", "TikTok")
    for values in table.values():
        for key, value in tuple(values.items()):
            repaired = str(value)
            for token in tokens:
                repaired = re.sub(rf"(?<=[a-z])({re.escape(token)})", r" \1", repaired)
                repaired = re.sub(rf"({re.escape(token)})(?=[a-z])", r"\1 ", repaired)
            values[key] = repaired
    return table

def public_hub_copy(lang: str | None = None) -> dict[str, str]:
    """Return direct customer-facing Hub copy for a supported locale."""

    locale = public_copy_locale(lang)
    copy = dict(_PUBLIC_HUB_COPY[locale])
    copy.update(_PUBLIC_HUB_AUXILIARY_COPY[locale])
    copy.update({"start_legal_notice": _PUBLIC_START_LEGAL_COPY[locale]})
    copy.update(_PUBLIC_ROOT_NAVIGATION_COPY[locale])
    copy.update(_PUBLIC_CHAT_ROOT_COPY[locale])
    copy.update(_PUBLIC_CHAT_ATTACHMENT_COPY[locale])
    copy.update(_PUBLIC_ROOT_SCREEN_COPY[locale])
    copy.update(_PUBLIC_FREE_HUB_ROOT_COPY[locale])
    copy.update(_PUBLIC_FREE_HUB_FLOW_COPY[locale])
    copy.update(_PUBLIC_IMAGE_ROOT_COPY[locale])
    copy.update(_PUBLIC_IMAGE_WARRANTY_COPY[locale])
    copy.update(_PUBLIC_AUDIO_ROOT_COPY[locale])
    copy.update(_PUBLIC_DEEP_MENU_COPY[locale])
    copy.update({f"freehub_task_{key}": value for key, value in _PUBLIC_FREE_TASK_LABELS[locale].items()})
    copy.update(_PUBLIC_NATIVE_DEEP_FLOW_COPY[locale])
    copy.update(_PUBLIC_DOCS_MEMORY_NATIVE_COPY[locale])
    copy.update(_PUBLIC_DOCS_ACTION_NATIVE_COPY[locale])
    copy.update(_PUBLIC_MEMORY_NOTE_FIELD_COPY[locale])
    copy.update(_PUBLIC_ROOT_FLOW_COPY[locale])
    copy.update(_PUBLIC_ROOT_ACTION_COPY[locale])
    copy.update(_PUBLIC_FEEDBACK_PROMPT_COPY[locale])
    copy.update(_PUBLIC_MEMORY_STORAGE_COPY[locale])
    copy.update(_PUBLIC_TRANSLATION_FLOW_COPY[locale])
    copy.update(_PUBLIC_TRANSLATION_MEDIA_COPY[locale])
    copy.update(_PUBLIC_TRANSLATION_COMMAND_COPY[locale])
    copy.update(_PUBLIC_INTERNATIONAL_SUPPORT_COPY.get(locale, {}))
    copy.update(_PUBLIC_SUPPORT_PROFILE_COPY[locale])
    copy.update(_PUBLIC_SUPPORT_CHILD_LABELS[locale])
    copy.update(_PUBLIC_SUPPORT_CHILD_TEXT[locale])
    copy.update(_PUBLIC_SUPPORT_DEEP_COPY[locale])
    copy.update(_PUBLIC_SUPPORT_TICKET_COPY[locale])
    copy.update({
        f"support_ticket_status_{code}": _PUBLIC_SUPPORT_TICKET_STATUS_COPY[locale][index]
        for index, code in enumerate(_PUBLIC_SUPPORT_TICKET_STATUS_CODES)
    })
    copy.update({
        f"support_ticket_priority_{code}": _PUBLIC_SUPPORT_TICKET_PRIORITY_COPY[locale][index]
        for index, code in enumerate(_PUBLIC_SUPPORT_TICKET_PRIORITY_CODES)
    })
    copy.update(_PUBLIC_PACKAGE_NAVIGATION_COPY.get(locale, {}))
    copy.update(_PUBLIC_ACCOUNT_FLOW_COPY[locale])
    return copy


def public_image_flow_copy(lang: str | None = None) -> dict[str, str]:
    """Return native labels for the Image deep-flow presentation shell."""

    locale = public_copy_locale(lang)
    return dict(_PUBLIC_IMAGE_FLOW_COPY.get(locale, _PUBLIC_IMAGE_FLOW_COPY["en"]))


def public_image_screen_copy(lang: str | None = None) -> dict[str, str]:
    """Return native status/instruction copy for Image deep-flow screens."""

    locale = public_copy_locale(lang)
    return dict(_PUBLIC_IMAGE_SCREEN_COPY.get(locale, _PUBLIC_IMAGE_SCREEN_COPY["en"]))


def public_guide_navigation_copy(lang: str | None = None) -> dict[str, str]:
    """Return native labels for legacy guide-entry buttons when available."""

    locale = public_copy_locale(lang)
    copy = dict(_PUBLIC_HUB_COPY[locale])
    copy.update(_PUBLIC_HUB_AUXILIARY_COPY[locale])
    # Chinese keeps its established, more specific guide wording.  The other
    # locales use their already translated hub labels so the legacy guide
    # keyboard never silently falls back to English.
    explicit = dict(PUBLIC_GUIDE_NAVIGATION_I18N.get(locale, {}))
    return {
        "quick_start": explicit.get("quick_start") or copy["guide_label"],
        "create_image": explicit.get("create_image") or copy["image_label"],
        "create_video": explicit.get("create_video") or copy["video_label"],
        "trend_video": explicit.get("trend_video") or copy["video_label"],
        "video_music": explicit.get("video_music") or copy["music_label"],
        "credits_topup": explicit.get("credits_topup") or copy["topup_label"],
        "faq_refunds": explicit.get("faq_refunds") or copy["feedback_label"],
        "download_pricing": explicit.get("download_pricing") or copy["guide_label"],
        "download_guide": explicit.get("download_guide") or copy["guide_label"],
    }


def public_copy_locale(lang: str | None = None) -> str:
    """Return the public-copy locale without changing user or market state."""

    value = str(lang or "").strip().lower().replace("_", "-")
    aliases = {
        "vi-vn": "vi", "zh-cn": "zh", "cn": "zh", "pt-br": "pt",
        "fil-ph": "fil", "id-id": "id",
    }
    value = aliases.get(value, value)
    return value if value in PUBLIC_COPY_LOCALES else "en"


