assert all(len(row) == len(_PUBLIC_TOPUP_DEEP_KEYS) for row in _PUBLIC_TOPUP_DEEP_VALUES.values())
_PUBLIC_TOPUP_DEEP_COPY = {
    locale: dict(zip(_PUBLIC_TOPUP_DEEP_KEYS, values, strict=True))
    for locale, values in _PUBLIC_TOPUP_DEEP_VALUES.items()
}

_PUBLIC_TOPUP_MINUTES_UNIT = {
    "vi": "phút", "en": "minutes", "zh": "分钟", "es": "minutos",
    "pt": "minutos", "fr": "min", "de": "Minuten", "ja": "分",
    "ko": "분", "hi": "मिनट", "ar": "دقيقة", "ru": "минут",
    "tr": "dakika", "th": "นาที", "fil": "minuto", "it": "minuti",
    "id": "menit",
}
assert set(_PUBLIC_TOPUP_MINUTES_UNIT) == set(PUBLIC_COPY_LOCALES)


def public_topup_deep_copy(lang: str | None = None) -> dict[str, str]:
    """Return the complete presentation-only top-up row for ``lang``."""

    locale = public_copy_locale(lang)
    result = dict(_PUBLIC_TOPUP_DEEP_COPY[locale])
    result["minutes_unit"] = _PUBLIC_TOPUP_MINUTES_UNIT[locale]
    return result


