# Native account rows for the remaining international locales.  Each row is
# derived from the English canonical field order above and is deliberately
# explicit: no sentence is assembled from unrelated labels at runtime.
_ACCOUNT_EN = _PUBLIC_ACCOUNT_FLOW_COPY["en"]


def _native_account_row(locale: str, overrides: dict[str, str]) -> tuple[str, ...]:
    missing = set(_ACCOUNT_EN) - set(overrides)
    if missing:
        raise ValueError(f"incomplete account-flow copy for {locale}: {sorted(missing)}")
    return tuple(overrides[key] for key in _ACCOUNT_EN)


