for _locale, _values in _PUBLIC_ACCOUNT_FLOW_VALUES.items():
    if len(_values) != len(_PUBLIC_ACCOUNT_FLOW_KEYS):
        raise ValueError(f"account-flow copy key mismatch for {_locale}: {len(_values)} != {len(_PUBLIC_ACCOUNT_FLOW_KEYS)}")
    _PUBLIC_ACCOUNT_FLOW_COPY[_locale] = dict(zip(_PUBLIC_ACCOUNT_FLOW_KEYS, _values, strict=True))

for _locale, _values in _PUBLIC_ACCOUNT_FLOW_EXTRA_COPY.items():
    if len(_values) != len(_PUBLIC_ACCOUNT_FLOW_EXTRA_KEYS):
        raise ValueError(f"account-flow extra copy key mismatch for {_locale}")
    _PUBLIC_ACCOUNT_FLOW_COPY[_locale].update(dict(zip(_PUBLIC_ACCOUNT_FLOW_EXTRA_KEYS, _values, strict=True)))

assert set(_PUBLIC_ACCOUNT_FLOW_COPY) == set(PUBLIC_COPY_LOCALES)


def public_account_flow_copy(lang: str | None = None) -> dict[str, str]:
    """Return native account/referral/member/birthday/top-up presentation copy."""

    return dict(_PUBLIC_ACCOUNT_FLOW_COPY[public_copy_locale(lang)])


def _public_locale_copy(lang: str | None = None) -> dict[str, str]:
    return dict(_PUBLIC_LOCALE_COPY.get(public_copy_locale(lang), _PUBLIC_LOCALE_COPY["en"]))


def _public_copy_labels(lang: str | None = None) -> dict[str, str]:
    locale = public_copy_locale(lang)
    if locale == "vi":
        return {"home": "← Trang chủ", "pricing": "Bảng giá TOAN AAS", "guide": "Hướng dẫn sử dụng TOAN AAS"}
    copy = _public_locale_copy(locale)
    return {"home": f"← {copy['home']}", "pricing": copy["pricing"], "guide": copy["guide"]}


def public_page_title(page: str, lang: str | None = None) -> str:
    """Return the existing public native label for a pricing or guide page."""

    labels = _public_copy_labels(lang)
    key = "pricing" if str(page or "").strip().lower() == "pricing" else "guide"
    return labels[key]


